package org.novasos.healthysv2.messaging;
import static org.novasos.healthysv2.messaging.api.MessagingDtos.*;import java.security.Principal;import java.util.UUID;import jakarta.validation.Valid;import org.springframework.messaging.handler.annotation.*;import org.springframework.security.core.Authentication;import org.springframework.stereotype.Controller;
@Controller class ConversationSocketController{private final ConversationService service;ConversationSocketController(ConversationService service){this.service=service;}@MessageMapping("/conversations/{id}/messages")void send(@DestinationVariable UUID id,@Valid SendMessageRequest request,Principal principal){if(!(principal instanceof Authentication authentication))throw new IllegalStateException("Authenticated principal required");service.send(id,request,authentication);}}
